class Solution {
public:
    vector<int> exclusiveTime(int n, vector<string>& logs) {
        vector<int> res(n, 0);
        struct E { int id, t; bool start; };
        vector<E> ev;
        for (auto& l : logs) {
            int p1 = l.find(':'), p2 = l.rfind(':');
            int id = stoi(l.substr(0, p1));
            bool st = l.substr(p1 + 1, p2 - p1 - 1) == "start";
            int t = stoi(l.substr(p2 + 1));
            ev.push_back({id, t, st});
        }
        stack<int> stk;
        for (size_t i = 0; i + 1 < ev.size(); ++i) {
            int span = ev[i + 1].t - ev[i].t;
            if (ev[i].start && !ev[i + 1].start) span++;
            if (!ev[i].start && !ev[i + 1].start) span++;
            if (ev[i].start) {
                stk.push(ev[i].id);
                res[stk.top()] += span;
            } else {
                stk.pop();
                if (!stk.empty()) res[stk.top()] += span;
            }
        }
        return res;
    }
};

