class Solution {
    public int[] exclusiveTime(int n, List<String> logs) {
        int[] res = new int[n];
        Deque<Integer> stack = new ArrayDeque<>();
        String[][] ev = new String[logs.size()][];
        for (int i = 0; i < logs.size(); i++) ev[i] = logs.get(i).split(":");
        for (int i = 0; i + 1 < ev.length; i++) {
            boolean curStart = ev[i][1].equals("start");
            boolean nextStart = ev[i + 1][1].equals("start");
            int span = Integer.parseInt(ev[i + 1][2]) - Integer.parseInt(ev[i][2]);
            if (curStart && !nextStart) span++;
            if (!curStart && !nextStart) span++;
            if (curStart) {
                stack.push(Integer.parseInt(ev[i][0]));
                res[stack.peek()] += span;
            } else {
                stack.pop();
                if (!stack.isEmpty()) res[stack.peek()] += span;
            }
        }
        return res;
    }
}

